python -c 'exec("import os\nos.environ.setdefault(\"QT_QPA_PLATFORM\",\"offscreen\")\nimport sys,time,traceback,tempfile\nfrom pathlib import Path\nNL=chr(10)\nP=[];F=[]\ndef T(n,f):\n    t0=time.perf_counter()\n    try:\n        f();P.append((n,(time.perf_counter()-t0)*1000))\n    except Exception as e:\n        F.append((n,repr(e),traceback.format_exc()))\ndef t_imports():\n    import Chert_Managers\n    import Markdown_Chert\n    import Live_Preview\n    import Graph_Chert\n    import Theme_Chert\n    import Panels_Chert\n    import Dialogs_Chert\n    import UI_Chert\nT(\"imports_all\",t_imports)\nfrom PyQt6.QtWidgets import QApplication\napp=QApplication.instance() or QApplication(sys.argv)\ndef t_md():\n    from Markdown_Chert import MarkdownRenderer\n    r=MarkdownRenderer()\n    cases=[\"\",\"# h1\"+NL+\"## h2\"+NL+\"### h3\",\"**b** _i_ `c` ~~s~~ ==h==\",\"[[WikiLink]] [[Target|Alias]]\",\"> q\"+NL+\"> m\",\"| a | b |\"+NL+\"|---|---|\"+NL+\"| 1 | 2 |\",\"```python\"+NL+\"print(1)\"+NL+\"```\",\"```mermaid\"+NL+\"graph TD\"+NL+\"A-->B\"+NL+\"```\",\"$$x^2+y^2=z^2$$\",\"inline $x$ math\",\"- [ ] t\"+NL+\"- [x] d\",\"***bi***\",\"---\",\"> [!note] callout\",\"unclosed [[wl\",\"emoji 😀 中文\",NL.join([\"a\"]*3000),\"# \"+\"x\"*5000]\n    for i,c in enumerate(cases):\n        h=r.render(c,{\"WikiLink\",\"Target\"})\n        assert isinstance(h,str) and len(h)>0,\"case %d\"%i\nT(\"md_20_edge_cases\",t_md)\ndef t_md2():\n    from Markdown_Chert import MarkdownRenderer\n    r=MarkdownRenderer()\n    h=r.render(\"[[WL]]\",{\"WL\"})\n    assert \"chert://open/\" in h\n    h2=r.render(\"```mermaid\"+NL+\"graph TD\"+NL+\"A-->B\"+NL+\"```\",set())\n    assert \"mermaid\" in h2\n    big=NL.join([\"## S%d\"%i+NL+NL+\"P %d **b** [[L%d]]\"%(i,i,i) for i in range(500)])\n    t0=time.perf_counter()\n    r.render(big,set())\n    dt=time.perf_counter()-t0\n    assert dt<3.0,\"slow %.2f\"%dt\nT(\"md_anchors_stress\",t_md2)\ndef t_lp():\n    from Live_Preview import LivePreviewPane\n    p=LivePreviewPane(None,vault=None,settings=None,rel_path=\"t.md\")\n    p.load(\"# Hello\"+NL+NL+\"**world**\"+NL+NL+\"[[WikiLink]]\")\n    assert \"Hello\" in p.text()\n    st=p.render_stats()\n    assert st[\"renders\"]>=1\nT(\"live_preview_load\",t_lp)\ndef t_lp2():\n    from Live_Preview import LivePreviewPane\n    p=LivePreviewPane(None,vault=None,settings=None,rel_path=\"u.md\")\n    p.load(\"# 中文 😀\")\n    assert \"中文\" in p.text()\n    p2=LivePreviewPane(None,vault=None,settings=None,rel_path=\"e.md\")\n    p2.load(\"\")\n    assert p2.text()==\"\"\nT(\"live_preview_unicode_empty\",t_lp2)\ndef t_lp3():\n    from Live_Preview import LivePreviewPane\n    p=LivePreviewPane(None,vault=None,settings=None,rel_path=\"h.md\")\n    p.load(\"# a\")\n    p.editor.blockSignals(True)\n    p.editor.setPlainText(\"# edited\")\n    p.editor.blockSignals(False)\n    p._on_content_changed(\"# edited\")\n    p._pending=True\n    p._render_now()\n    assert \"edited\" in p.text()\nT(\"live_preview_hidden_edit\",t_lp3)\ndef t_g():\n    from Graph_Chert import ForceGraphView\n    v=ForceGraphView()\n    v.build([\"a.md\",\"b.md\",\"c.md\"],[(\"a.md\",\"b.md\"),(\"b.md\",\"c.md\"),(\"a.md\",\"c.md\")])\n    assert len(v.nodes)==3 and len(v.edges)==3\nT(\"graph_triangle\",t_g)\ndef t_g2():\n    from Graph_Chert import ForceGraphView\n    v=ForceGraphView()\n    v.build([\"n%d.md\"%i for i in range(60)],[(\"n%d.md\"%i,\"n%d.md\"%(i+1)) for i in range(59)])\n    t0=time.perf_counter()\n    for _ in range(20): v._tick_internal()\n    dt=(time.perf_counter()-t0)*1000\n    assert dt<3000,\"slow %.0f\"%dt\nT(\"graph_60_nodes_20_ticks\",t_g2)\ndef t_g3():\n    from Graph_Chert import ForceGraphView\n    from PyQt6.QtWidgets import QGraphicsScene\n    v=ForceGraphView()\n    assert v.scene.itemIndexMethod()==QGraphicsScene.ItemIndexMethod.NoIndex\nT(\"graph_no_bsp_conflict\",t_g3)\ndef t_g4():\n    from Graph_Chert import ForceGraphView\n    n=300\n    v=ForceGraphView()\n    paths=[\"n%d.md\"%i for i in range(n)]\n    edges=[(\"n%d.md\"%i,\"n%d.md\"%((i*7)%n)) for i in range(n)]\n    t0=time.perf_counter()\n    v.build(paths,edges)\n    for _ in range(5): v._tick_internal()\n    dt=(time.perf_counter()-t0)*1000\n    assert dt<5000,\"slow %.0f\"%dt\nT(\"graph_stress_300_nodes\",t_g4)\ndef t_v():\n    from Chert_Managers import VaultManager,BacklinkIndex,SearchIndex,TagIndex\n    with tempfile.TemporaryDirectory() as d:\n        d=Path(d)\n        vault=VaultManager(d)\n        vault.write(\"note.md\",\"# n\"+NL+\"[[other]] #tag1\")\n        vault.write(\"other.md\",\"# o\"+NL+\"[[note]] #tag2\")\n        vault.write(\"sub/deep.md\",\"# d\"+NL+\"[[note]]\")\n        notes=vault.list_notes()\n        assert len(notes)==3,\"got %d: %s\"%(len(notes),notes)\n        b=BacklinkIndex(d/\".chert\"/\"b.db\")\n        for r in (\"note.md\",\"other.md\",\"sub/deep.md\"):\n            b.index_file(r,vault.read(r))\n        bl=b.backlinks(\"note.md\")\n        srcs={x[\"source\"] for x in bl}\n        assert \"other.md\" in srcs and \"sub/deep.md\" in srcs,\"bl: %s\"%srcs\n        s=SearchIndex(d/\".chert\"/\"s.db\")\n        for r in (\"note.md\",\"other.md\",\"sub/deep.md\"):\n            s.index(r,Path(r).stem,vault.read(r))\n        assert len(s.search(\"other\"))>=1\n        tg=TagIndex(d/\".chert\"/\"t.db\")\n        for r in (\"note.md\",\"other.md\"):\n            tg.index_file(r,vault.read(r))\n        tags=dict(tg.all_tags())\n        assert \"tag1\" in tags and \"tag2\" in tags,\"tags: %s\"%tags\n        b.close();s.close();tg.close()\nT(\"vault_full_pipeline\",t_v)\ndef t_th():\n    from Theme_Chert import get_theme,stylesheet\n    for n in (\"dark\",\"light\"):\n        s=stylesheet(get_theme(n))\n        assert len(s)>500\nT(\"theme_both\",t_th)\ndef t_mw():\n    from UI_Chert import MainWindow\n    with tempfile.TemporaryDirectory() as d:\n        d=Path(d)\n        (d/\"note.md\").write_text(\"# hi\"+NL+\"[[other]]\",encoding=\"utf-8\")\n        (d/\"other.md\").write_text(\"# other\",encoding=\"utf-8\")\n        w=MainWindow(d)\n        assert w.ribbon and w.left_sidebar and w.right_sidebar and w.editor_area and w.status\n        w.close()\nT(\"mainwindow_offscreen\",t_mw)\ndef t_pn():\n    from Panels_Chert import FileExplorerPanel,OutlinePanel\n    with tempfile.TemporaryDirectory() as d:\n        d=Path(d)\n        (d/\"a.md\").write_text(\"# a\"+NL+\"## a1\"+NL+\"### a1a\",encoding=\"utf-8\")\n        vault=VaultManager(d)\n        fe=FileExplorerPanel(vault)\n        fe.rebuild()\n        assert fe.tree.topLevelItemCount()>=1\n        op=OutlinePanel()\n        op.set_content(\"# a\"+NL+\"## a1\"+NL+\"### a1a\")\n        assert op.tree.topLevelItemCount()>=1\nT(\"panels_offscreen\",t_pn)\nprint()\nprint(\"=\"*60)\nfor n,ms in P: print(\"  PASS  %-32s %7.1fms\"%(n,ms))\nfor n,e,tb in F:\n    print(\"  FAIL  %s: %s\"%(n,e))\n    print(tb)\nprint(\"=\"*60)\nprint(\"%d passed, %d failed\"%(len(P),len(F)))\nsys.exit(1 if F else 0)")'